/**
 * Study AS corpus generator — prints each corpus/pdf-pipeline/src/*.html
 * design to a US-letter PDF in corpus/pdf-pipeline/pdf/ via headless
 * Chromium, then writes corpus/pdf-pipeline/manifest.json with sha256
 * hashes in registered run order (T1 → T2 → T3, alphabetical within tier).
 *
 * The COMMITTED PDFs are the corpus — scored runs ingest those exact bytes
 * (checked against the manifest before any scored call). Chromium version
 * drift can change regenerated bytes; regeneration after the first scored
 * run would be a corpus swap and is not allowed (docs/BRIEF-AS.md).
 *
 *   bun scripts/generate-pdf-pipeline-corpus.ts
 */

import { mkdir, readdir } from "node:fs/promises";
import { resolve } from "node:path";

import { chromium } from "playwright";

const CORPUS_DIR = resolve(import.meta.dir, "../corpus/pdf-pipeline");

async function sha256Hex(bytes: Uint8Array): Promise<string> {
	const hasher = new Bun.CryptoHasher("sha256");
	hasher.update(bytes);
	return hasher.digest("hex");
}

async function main() {
	const srcDir = `${CORPUS_DIR}/src`;
	const pdfDir = `${CORPUS_DIR}/pdf`;
	await mkdir(pdfDir, { recursive: true });

	const htmlFiles = (await readdir(srcDir))
		.filter((f) => f.endsWith(".html"))
		.sort();
	if (htmlFiles.length === 0) {
		console.error(`No HTML sources in ${srcDir}`);
		process.exit(1);
	}

	const browser = await chromium.launch();
	const manifest: { slug: string; sha256: string; bytes: number }[] = [];
	try {
		const page = await browser.newPage();
		for (const file of htmlFiles) {
			const slug = file.replace(/\.html$/, "");
			await page.goto(`file://${srcDir}/${file}`, {
				waitUntil: "networkidle",
			});
			const pdf = await page.pdf({
				format: "Letter",
				margin: { bottom: 0, left: 0, right: 0, top: 0 },
				printBackground: true,
			});
			const bytes = new Uint8Array(pdf);
			await Bun.write(`${pdfDir}/${slug}.pdf`, bytes);
			manifest.push({
				bytes: bytes.length,
				sha256: await sha256Hex(bytes),
				slug,
			});
			console.log(
				`${slug}.pdf — ${(bytes.length / 1024).toFixed(0)} KB, sha256 ${manifest.at(-1)?.sha256.slice(0, 16)}…`,
			);
		}
	} finally {
		await browser.close();
	}

	await Bun.write(
		`${CORPUS_DIR}/manifest.json`,
		`${JSON.stringify(manifest, null, "\t")}\n`,
	);
	console.log(`\nManifest written: ${manifest.length} items.`);
}

await main();
